{
  "gate_token": "MC9QVzLFUkGwZFQUiI9OTQ",
  "title": "The Mirror Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined city.",
      "visual_description": "A windswept hill at dusk overlooking a shattered skyline of broken towers and torn banners, ink-stained coat fluttering as a brass compass spins.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of false paths.",
      "visual_description": "A close-up of an oil lamp held aloft, its single flame-eye glaring at a fork in the road where one path glimmers with gold and the other with shadow.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the broken castle gates.",
      "visual_description": "A small clockwork fox perched on rubble before enormous iron gates hanging off their hinges, blue glass eyes glinting, key-wind tail ticking.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver slips in through a stained window.",
      "visual_description": "A figure in a clear diving helmet emerges from a tall cathedral window as if surfacing from water, coat catching colored light from broken panes.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The party regroups beneath torn royal banners.",
      "visual_description": "Four companions huddle in a ruined plaza beneath tattered crimson banners stitched with faded crests, dust drifting in slanted light.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Rumor of a winged beast rolls across the rooftops.",
      "visual_description": "Silhouette of wide wings flicker across a smoky sky behind shattered spires; the lamp's eye narrows as the cartographer presses against a wall.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "An armored patrol clatters past in the alley.",
      "visual_description": "From a low crevice, lantern light and steel boots pass within inches; the tin fox freezes mid-step, its tail-key stilled.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "They find the sleeping tax collector slumped at a checkpoint.",
      "visual_description": "A plump official snores at a toll desk, ledger book under his cheek, stamped papers stuck to his sleeves, ink pooling near his fingers.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Mara forges a pass using the dozing stamps.",
      "visual_description": "Close on ink-stained hands carefully lifting a brass seal from the sleeper's sleeve, the lamp tilted to light the page.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "A cursed tower hums with locked magic.",
      "visual_description": "A leaning black tower wrapped in glowing chains of runes, purple light bleeding from its arrow slits over a courtyard of cracked statues.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caguse": "",
      "caption": "The oracle lamp deciphers the door's riddle.",
      "visual_description": "The flame-eye projects shifting glyphs onto a tall iron door covered in interlocking rings, the cartographer copying symbols into a notebook.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "Glass Diver dives through a mirror into the cell.",
      "visual_description": "A tall cracked mirror ripples like water as the helmeted rescuer plunges in headfirst, coat trailing reflections of the ruined city.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox finds the captive in a sunken vault.",
      "visual_description": "The clockwork fox stands on a stone shelf in a flooded vault, blue eyes lighting a small figure curled inside a glass cage half-submerged in water.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Alarms wake the tax collector, who only grumbles.",
      "visual_description": "Bells clang above a chaotic street while the official sits up, eyes half-closed, ledger sliding off his lap, oblivious to fires beyond the window.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "Patrols converge as the team flees through a magic door.",
      "visual_description": "A glowing rectangle of light splits a stone wall in a narrow lane; the four companions leap through as armored shapes round the corner.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The oracle lamp warns the bridge will not hold long.",
      "visual_description": "A long stone bridge over a black chasm, runes crumbling at its base; the lamp's flame stretches into a pointing finger toward the far side.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across as the bridge cracks behind them.",
      "visual_description": "Mid-stride on collapsing stones, the diver carries a small wrapped figure, the fox bounding ahead, lamp swinging wildly, chasms gaping below.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far ridge, they watch the city burn.",
      "visual_description": "Four silhouettes on a windy bluff at dawn, the ruined city smoldering in the valley behind them, the brass compass finally pointing home.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

